import React from 'react';
import './support.css';

function Support() {
  return (
    <div className="support">
        <h1>Support</h1>
        <h5>We can always help you by phone call</h5>
        <h1>123456789</h1>
        <h5>Or you can send us an email</h5>
        <h1>inventhor@support.no</h1>
    </div>
  )
}

export default Support;
